// Checks a booking before it is saved. Nothing is saved unless every check passes.
const q = $('When Called by Agent').first().json;
const villas = $('Read Villas').all().map(i => i.json).filter(v => v.Villa_ID);
const bookings = $('Read Bookings').all().map(i => i.json).filter(b => b.Villa_ID);
const s = v => (v === undefined || v === null) ? '' : String(v).trim();
const num = v => { const n = Number(s(v).replace(/[^0-9.]/g, '')); return isNaN(n) ? 0 : n; };
const MON = { jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11 };
function day(v) {
  const t = s(v); if (!t) return null;
  let m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/); if (m) return Date.UTC(+m[1], +m[2]-1, +m[3]);
  m = t.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/); if (m) return Date.UTC(+m[3], +m[2]-1, +m[1]);
  m = t.match(/^(\d{1,2})\s*([A-Za-z]{3})[A-Za-z]*\s*(\d{4})?/); if (m && MON[m[2].toLowerCase()] !== undefined) return Date.UTC(m[3] ? +m[3] : new Date().getUTCFullYear(), MON[m[2].toLowerCase()], +m[1]);
  return null;
}
const iso = d => new Date(d).toISOString().slice(0, 10);
const now = new Date();
const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());

const problems = [];
const name = s(q.customer_name);
let phone = s(q.customer_whatsapp).replace(/[^0-9]/g, '');
if (phone.length === 10) phone = '91' + phone;
if (phone.length < 11 || phone.length > 13) problems.push('a valid phone number (10 digits) is missing');
if (name.length < 2) problems.push("the customer's full name is missing");
const guests = num(q.guests);
if (!guests) problems.push('the number of guests is missing');
const ci = day(q.check_in), co = day(q.check_out);
let nights = null;
if (ci === null || co === null) problems.push('check-in or check-out date is missing');
else {
  nights = Math.round((co - ci) / 86400000);
  if (nights < 1) problems.push('check-out must be after check-in');
  if (ci < today) problems.push('the check-in date is in the past');
}
const v = villas.find(x => s(x.Villa_ID).toUpperCase() === s(q.villa_id).toUpperCase());
if (!v) problems.push('that villa was not found');
else {
  if (s(v.Booking_Status).toLowerCase() !== 'available') problems.push('the villa is not available for booking');
  if (guests && num(v.Max_Guests) < guests) problems.push('the villa fits only ' + num(v.Max_Guests) + ' guests');
  if (ci !== null && co !== null && nights >= 1) {
    const af = day(v.Available_From), at = day(v.Available_To);
    if (af !== null && ci < af) problems.push('the villa is only available from ' + iso(af));
    if (at !== null && co > at) problems.push('the villa is only available until ' + iso(at));
    if (nights < num(v.Minimum_Nights)) problems.push('the minimum stay is ' + num(v.Minimum_Nights) + ' nights');
    const clash = bookings.some(b => s(b.Villa_ID).toUpperCase() === s(v.Villa_ID).toUpperCase()
      && s(b.Booked).toLowerCase().startsWith('y')
      && day(b.Check_In) !== null && day(b.Check_Out) !== null
      && day(b.Check_In) < co && day(b.Check_Out) > ci);
    if (clash) problems.push('the villa is already booked for these dates');
  }
}
if (problems.length) return [{ json: { ok: false, reason: problems.join('; ') } }];

// Unique booking ID: date-time plus 3 random characters, checked against existing IDs.
const used = new Set(bookings.map(b => s(b.Booking_ID)));
const pad = n => String(n).padStart(2, '0');
const local = new Date(now.getTime() + 5.5 * 3600000); // India time
const stamp = String(local.getUTCFullYear()).slice(2) + pad(local.getUTCMonth() + 1) + pad(local.getUTCDate()) + '-' + pad(local.getUTCHours()) + pad(local.getUTCMinutes());
let id;
do { id = 'BK-' + stamp + '-' + Math.random().toString(36).slice(2, 5).toUpperCase(); } while (used.has(id));
const rate = num(v.Nightly_Rate_INR);
return [{ json: {
  ok: true,
  Booking_ID: id,
  Booked_At: local.toISOString().slice(0, 16).replace('T', ' '),
  Customer_Name: name,
  Customer_WhatsApp: phone,
  Guests: guests,
  Villa_ID: s(v.Villa_ID),
  Villa_Name: s(v.Villa_Name),
  Check_In: iso(ci),
  Check_Out: iso(co),
  Nights: nights,
  Total_Amount_INR: rate * nights,
  Payment_Status: 'Pending',
  Booked: 'yes',
  Nightly_Rate_INR: rate,
  Location: s(v.Location),
  Property_Type: s(v.Property_Type),
  Max_Guests: num(v.Max_Guests),
  Amenities: s(v.Amenities),
  Owner_Name: s(v.Owner_Name) || 'not on file',
  Owner_Phone: s(v.Owner_Phone) || 'not on file',
  Channel: s(q.channel) || 'whatsapp',
} }];

